#' Sample Size Estimation
#'
#' 
#' @param data .
#' @param power .
#' @param alpha .
#' @param r .
#' @param delta .
#' @param sel .
#' @param cssd1 .
#' @param cssd2 .
#' @param csnsf .
#' @param rmsd1 .
#' @param rmsd2 .
#' @param rmnsf .
#' @param input .
#' @param v .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$sse$ocr} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$sse$rop} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$sse$p} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$sse$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$to$d} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$to$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$to$c} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
TOSTSampleSize <- function(
    data,
    power = 0.8,
    alpha = 0.05,
    r = 4,
    delta = 0,
    sel = 1,
    cssd1 = 0.5,
    cssd2 = 0.5,
    csnsf = 1,
    rmsd1 = 0.5,
    rmsd2 = 0.5,
    rmnsf = 1,
    input,
    v = 3) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("TOSTSampleSize requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- TOSTSampleSizeOptions$new(
        power = power,
        alpha = alpha,
        r = r,
        delta = delta,
        sel = sel,
        cssd1 = cssd1,
        cssd2 = cssd2,
        csnsf = csnsf,
        rmsd1 = rmsd1,
        rmsd2 = rmsd2,
        rmnsf = rmnsf,
        input = input,
        v = v)

    analysis <- TOSTSampleSizeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

